## 🛒 Add Item (Merge Logic + Stock Validation)

```js
exports.addToCart = async (req, res) => {
  const { userId, productId, quantity } = req.body;

  if (quantity <= 0) {
    return res.status(400).json({ message: "Quantity must be greater than 0" });
  }

  const client = await pool.connect();

  try {
    await client.query("BEGIN");

    const cart = await getOrCreateCart(userId, client);

    // Lock product row
    const productResult = await client.query(
      `SELECT * FROM products WHERE id = $1 FOR UPDATE`,
      [productId]
    );

    if (productResult.rows.length === 0)
      throw new Error("Product not found");

    const product = productResult.rows[0];

    const existingItem = await client.query(
      `SELECT * FROM cart_items
       WHERE cart_id = $1 AND product_id = $2 AND status = 'ACTIVE'
       FOR UPDATE`,
      [cart.id, productId]
    );

    let newQuantity = quantity;

    if (existingItem.rows.length > 0) {
      newQuantity += existingItem.rows[0].quantity;
    }

    if (newQuantity > product.stock) {
      throw new Error("Cannot exceed available stock");
    }

    if (existingItem.rows.length > 0) {
      await client.query(
        `UPDATE cart_items SET quantity = $1 WHERE id = $2`,
        [newQuantity, existingItem.rows[0].id]
      );
    } else {
      await client.query(
        `INSERT INTO cart_items (id, cart_id, product_id, quantity)
         VALUES ($1, $2, $3, $4)`,
        [uuidv4(), cart.id, productId, quantity]
      );
    }

    await client.query("COMMIT");
    res.json({ message: "Item added to cart" });

  } catch (err) {
    await client.query("ROLLBACK");
    res.status(400).json({ error: err.message });
  } finally {
    client.release();
  }
};
```

