## 💾 Save For Later

```js
exports.saveForLater = async (req, res) => {
  const { cartItemId } = req.body;

  await pool.query(
    `UPDATE cart_items SET status = 'SAVED'
     WHERE id = $1`,
    [cartItemId]
  );

  res.json({ message: "Item saved for later" });
};
