## 🛒 Cart Component

```jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';

export default function Cart({ userId }) {
  const [cart, setCart] = useState({ items: [], totalCents: 0 });

  const fetchCart = async () => {
    const res = await axios.get(`/api/cart/${userId}`);
    setCart(res.data);
  };

  useEffect(() => {
    fetchCart();
  }, []);

  const updateQuantity = async (id, quantity) => {
    await axios.put(`/api/cart/update`, { cartItemId: id, quantity });
    fetchCart();
  };

  const saveForLater = async (id) => {
    await axios.put(`/api/cart/save`, { cartItemId: id });
    fetchCart();
  };

  const formatMoney = cents =>
    (cents / 100).toLocaleString(undefined, {
      minimumFractionDigits: 2
    });

  return (
    <div>
      <h2>Shopping Cart</h2>

      {cart.items
        .filter(i => i.status === 'ACTIVE')
        .map(item => (
          <div key={item.id}>
            <h4>{item.name}</h4>
            <input
              type="number"
              value={item.quantity}
              onChange={(e) =>
                updateQuantity(item.id, Number(e.target.value))
              }
            />
            <p>${formatMoney(item.lineTotal)}</p>
            <button onClick={() => saveForLater(item.id)}>
              Save for later
            </button>
          </div>
        ))}

      <h3>Total: ${formatMoney(cart.totalCents)}</h3>

      <h2>Saved Items</h2>
      {cart.items
        .filter(i => i.status === 'SAVED')
        .map(item => (
          <div key={item.id}>{item.name}</div>
        ))}
    </div>
  );
}
```

